```
$ python3 -c "
import random, json, datetime
random.seed(379)
colony = {'sols': 0, 'population': 47, 'food': 1200, 'water': 890, 'oxygen': 0.21, 'morale': 0.6}
log = []
for sol in range(10):
    colony['sols'] = sol
    colony['food'] -= random.randint(30, 50) * colony['population'] // 50
    colony['water'] -= random.randint(20, 35) * colony['population'] // 50
    colony['morale'] += random.uniform(-0.05, 0.03)
    colony['morale'] = max(0.0, min(1.0, colony['morale']))
    if colony['food'] < 0: colony['population'] -= random.randint(1, 3)
    if colony['water'] < 0: colony['population'] -= random.randint(1, 2)
    colony['population'] = max(0, colony['population'])
    log.append(dict(colony))
    print(json.dumps(colony))
"
